<?php require_once __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/helpers.php';require_admin();$id=(int)($_GET['id']??0);$n=['title'=>'','notice_date'=>date('Y-m-d'),'description'=>'','pdf_path'=>'','pdf_original_name'=>'','status'=>'published'];if($id){$s=$pdo->prepare('SELECT * FROM notices WHERE id=?');$s->execute([$id]);$found=$s->fetch();if(!$found){http_response_code(404);exit('বিজ্ঞপ্তি পাওয়া যায়নি।');}$n=$found;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$n['title']=trim($_POST['title']??'');$n['notice_date']=$_POST['notice_date']??'';$n['description']=trim($_POST['description']??'');$n['status']=($_POST['status']??'published')==='draft'?'draft':'published';try{if($n['title']===''||mb_strlen($n['title'])>220)throw new RuntimeException('শিরোনাম দিন (সর্বোচ্চ ২২০ অক্ষর)।');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$n['notice_date'])||!strtotime($n['notice_date']))throw new RuntimeException('সঠিক তারিখ নির্বাচন করুন।');$oldOriginal=$n['pdf_original_name'];[$path,$original]=save_pdf($_FILES['pdf']??[], $n['pdf_path']?:null);if($original==='')$original=$oldOriginal;if($path==='' && $n['description']==='')throw new RuntimeException('বিজ্ঞপ্তির বিবরণ অথবা PDF—অন্তত একটি দিতে হবে।');if($id){$q=$pdo->prepare('UPDATE notices SET title=?,notice_date=?,description=?,pdf_path=?,pdf_original_name=?,status=? WHERE id=?');$q->execute([$n['title'],$n['notice_date'],$n['description'],$path,$original,$n['status'],$id]);}else{$q=$pdo->prepare('INSERT INTO notices(title,notice_date,description,pdf_path,pdf_original_name,status,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$n['title'],$n['notice_date'],$n['description'],$path,$original,$n['status'],$_SESSION['admin_id']]);}$n['pdf_path']=$path;$n['pdf_original_name']=$original;header('Location: notices.php');exit;}catch(Throwable $ex){$error=$ex->getMessage();}}$active='notices';$pageTitle=$id?'বিজ্ঞপ্তি সম্পাদনা':'নতুন বিজ্ঞপ্তি প্রকাশ';require __DIR__.'/_head.php';?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form class="panel" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-12"><label class="form-label fw-bold">বিজ্ঞপ্তির শিরোনাম *</label><input class="form-control" name="title" maxlength="220" required value="<?=e($n['title'])?>" placeholder="যেমন: পরীক্ষার সময়সূচি সংক্রান্ত বিজ্ঞপ্তি"></div><div class="col-12 col-md-5"><label class="form-label fw-bold">বিজ্ঞপ্তির তারিখ *</label><input class="form-control" type="date" name="notice_date" required value="<?=e($n['notice_date'])?>"></div><div class="col-12 col-md-7"><label class="form-label fw-bold">প্রকাশের অবস্থা</label><select class="form-select" name="status"><option value="published" <?=$n['status']==='published'?'selected':''?>>প্রকাশ করুন</option><option value="draft" <?=$n['status']==='draft'?'selected':''?>>খসড়া হিসেবে রাখুন</option></select></div><div class="col-12"><label class="form-label fw-bold">বিজ্ঞপ্তির বিবরণ / HTML (ঐচ্ছিক)</label><textarea class="form-control" name="description" rows="5" placeholder="বিজ্ঞপ্তির সংক্ষিপ্ত বিবরণ লিখুন"><?=e($n['description'])?></textarea><div class="form-text">নিরাপদ HTML সমর্থিত: &lt;p&gt;, &lt;strong&gt;, &lt;a href=&quot;...&quot;&gt;, তালিকা ও টেবিল। PDF-এর সঙ্গে ডাউনলোড লিংক যুক্ত করতে নিচের ফরম লিংক ব্যবহার করুন।</div><?php try{require_once __DIR__.'/../app/forms.php';aspi_forms_ensure($pdo);$formLinks=$pdo->query("SELECT title,slug FROM downloadable_forms WHERE status='published' ORDER BY title")->fetchAll();}catch(Throwable $e){$formLinks=[];} ?><div class="row g-2 mt-2"><div class="col-12 col-md-8"><select class="form-select" id="noticeFormLink"><option value="">প্রকাশিত ফরম থেকে লিংক নির্বাচন করুন</option><?php foreach($formLinks as $fl):?><option value="/live/form.php?slug=<?=e(rawurlencode($fl['slug']))?>"><?=e($fl['title'])?></option><?php endforeach;?></select></div><div class="col-12 col-md-4"><button class="btn btn-outline-primary w-100" type="button" id="insertNoticeFormLink">বিবরণে ফরম লিংক যুক্ত করুন</button></div></div><script>document.getElementById('insertNoticeFormLink')?.addEventListener('click',()=>{const s=document.getElementById('noticeFormLink'),t=document.querySelector('textarea[name="description"]');if(!s.value){alert('আগে একটি প্রকাশিত ফরম নির্বাচন করুন।');return;}const label=s.options[s.selectedIndex].text;const snippet='\n<p><a href="'+s.value+'" target="_blank" rel="noopener">'+label+' — ডাউনলোড / বিস্তারিত</a></p>\n';t.value+=snippet;t.focus();});</script></div><div class="col-12"><label class="form-label fw-bold">PDF বিজ্ঞপ্তি (ঐচ্ছিক) <?=$id?'(পরিবর্তন না করলে পুরোনো PDF থাকবে)':''?></label><input class="form-control" type="file" name="pdf" accept="application/pdf,.pdf"><div class="form-text">শুধু PDF, সর্বোচ্চ ২০ MB। বর্তমান ফাইল: <?=e($n['pdf_original_name']?:'নির্বাচিত হয়নি')?></div></div></div><hr class="my-4"><div class="d-flex gap-2 flex-wrap"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk me-1"></i> <?=$id?'পরিবর্তন সংরক্ষণ':'বিজ্ঞপ্তি সংরক্ষণ'?></button><a class="btn btn-light border" href="notices.php">বাতিল</a><?php if($id):?><a class="btn btn-outline-secondary ms-md-auto" target="_blank" href="../notice.php?id=<?=$id?>">প্রিভিউ</a><?php endif;?></div></form><?php require __DIR__.'/_foot.php';?>